\centering
\small
\caption{SciERC per-type LP selection (Qwen3-8B, $N{=}8$, $T{=}1.0$). Within-dataset, degeneracy alone does not predict LP effectiveness (Spearman $\rho{=}0.14$, $p{=}0.79$); additional type-specific factors likely modulate selection at this granularity.}
\label{tab:per_type_lp_scierc}
\begin{tabular}{lrrr}
\toprule
Entity Type & Degen.\% & LP $\Delta$ (pp) \\
\midrule
Task & 10.1 & $+$2.58 \\
Generic & 10.0 & $+$2.07 \\
Material & 20.0 & $+$0.91 \\
Metric & 12.5 & $-$0.06 \\
Method & 16.3 & $-$0.03 \\
OtherScientificTerm & 6.2 & $-$0.57 \\
\bottomrule
